def add_months_to_date(y, m, d, n_months):
    def days_in_month(year, month):
        if month == 2:
            leap = (year % 4 == 0 and year % 100 != 0) or year % 400 == 0
            return 29 if leap else 28
        if month in (4, 6, 9, 11):
            return 30
        return 31

    index = (y * 12 + m - 1) + n_months
    new_year, new_month = divmod(index, 12)
    new_month += 1
    max_day = days_in_month(new_year, new_month)
    return (new_year, new_month, min(d, max_day))

def is_undulating_number(n):
    digits = str(abs(n))
    if len(digits) < 3:
        return False
    if digits[0] == digits[1]:
        return False
    return all(a == b for a, b in zip(digits, digits[2:]))

def sum_divisors(n):
    def divisors(n):
        i = 1
        result = []
        while i * i <= n:
            if n % i == 0:
                result.append(i)
                if i != n // i:
                    result.append(n // i)
            i += 1
        return result
    return sum(divisors(n))

