def min_swaps_to_sort_strings(strings):
    n = len(strings)
    order = sorted(range(n), key=lambda i: strings[i])
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    for i in range(n):
        a, b = find(i), find(order[i])
        if a != b:
            parent[a] = b

    num_roots = len({find(i) for i in range(n)})
    return n - num_roots

