def prime_gap(n):
    def is_prime(x):
        if x < 2:
            return False
        i = 2
        while i * i <= x:
            if x % i == 0:
                return False
            i += 1
        return True

    primes = islice(filter(is_prime, count(2)), n + 1)
    p = list(primes)
    return p[-1] - p[-2]

